/**
 * @title A sidebar with a calendar
 * @description Account menu on top, a month calendar, and calendars you can show or hide. A wider sidebar (320px) so the calendar fits.
 * @route /calendar
 */
"use client";
import type { CSSProperties } from "react";
import { SidebarInset, SidebarProvider } from "@/components/ui/sidebar";
import { AppSidebar } from "@/components/app-sidebar";
import { SiteHeader } from "@/components/site-header";

export default function Page() {
  return (
    <SidebarProvider style={{ "--sidebar-width": "320px" } as CSSProperties}>
      <AppSidebar />
      <SidebarInset>
        <SiteHeader crumbs={[{ label: "Calendar", href: "#" }, { label: "October 2026" }]} />
        <div className="flex flex-1 flex-col gap-4 p-4 md:p-6">
          <h1 className="text-heading-h2">October 2026</h1>
          <div aria-hidden className="grid flex-1 grid-cols-7 gap-px overflow-hidden rounded-container border border-line-default bg-line-default">
            {Array.from({ length: 35 }, (_, i) => <div key={i} className="min-h-20 bg-surface p-2 text-caption-default text-fg-secondary">{((i + 27) % 31) + 1}</div>)}
          </div>
        </div>
      </SidebarInset>
    </SidebarProvider>
  );
}

"use client";
import { Button } from "@/components/ui/button";
import { Sidebar, SidebarContent, SidebarFooter, SidebarHeader, SidebarRail } from "@/components/ui/sidebar";
import { Calendars } from "@/components/calendars";
import { NavUser } from "@/components/nav-user";

export function AppSidebar() {
  return (
    <Sidebar label="Calendar">
      <SidebarHeader className="border-b border-line-default">
        <NavUser user={{ name: "Jane Cooper", email: "jane@acme.com" }} />
      </SidebarHeader>
      <SidebarContent>
        <Calendars />
      </SidebarContent>
      <SidebarFooter className="border-t border-line-default">
        <Button variant="secondary" leadingIcon="plus" className="w-full">New calendar</Button>
      </SidebarFooter>
      <SidebarRail />
    </Sidebar>
  );
}

"use client";
import { useState } from "react";
import { ChevronRight } from "lucide-react";
import { Calendar } from "@/components/ui/date";
import { Icon } from "@/components/ui/icon";
import { SidebarGroup, SidebarGroupContent, useDisclosure } from "@/components/ui/sidebar";

const groups = [
  { name: "My calendars", items: ["Personal", "Work", "Family"] },
  { name: "Favorites", items: ["Holidays", "Birthdays"] },
  { name: "Other", items: ["Travel", "Reminders", "Deadlines"] },
];
const dot = ["bg-brand", "bg-cat-teal-solid", "bg-cat-amber-solid", "bg-cat-red-solid", "bg-cat-lime-solid", "bg-cat-green-solid", "bg-cat-sky-solid", "bg-cat-orange-solid"];

function CalendarGroup({ name, items, offset }: { name: string; items: string[]; offset: number }) {
  const d = useDisclosure(true);
  const [on, setOn] = useState<Record<string, boolean>>(() => Object.fromEntries(items.map((i, k) => [i, k < 2])));
  return (
    <SidebarGroup className="py-1">
      <h3>
        <button type="button" {...d.triggerProps} className="flex h-8 w-full items-center justify-between rounded-control px-2 text-label-small text-fg-primary hover:bg-neutral-hover focus-visible:focus-ring">
          {name}
          <Icon name={ChevronRight} size={16} className={d.open ? "rotate-90 text-icon-secondary transition-transform" : "text-icon-secondary transition-transform"} />
        </button>
      </h3>
      <SidebarGroupContent {...d.contentProps}>
        <ul className="flex flex-col">
          {items.map((it, k) => (
            <li key={it}>
              <label className="flex h-8 cursor-pointer items-center gap-2 rounded-control px-2 text-body-small hover:bg-neutral-hover has-focus-visible:focus-ring">
                <input type="checkbox" checked={on[it]} onChange={(e) => setOn((o) => ({ ...o, [it]: e.target.checked }))} className="size-4 accent-[var(--ds-color-bg-brand)] outline-none" />
                <span aria-hidden className={`size-2 rounded-full ${dot[(offset + k) % dot.length]}`} />
                {it}
              </label>
            </li>
          ))}
        </ul>
      </SidebarGroupContent>
    </SidebarGroup>
  );
}

/** A month calendar and a list of calendars you can show or hide. */
export function Calendars() {
  const [date, setDate] = useState<Date | undefined>(undefined);
  return (
    <>
      <div className="flex justify-center px-2 [&>div]:border-0 [&>div]:shadow-none [&>div]:bg-transparent">
        <Calendar value={date} onChange={setDate} />
      </div>
      <div role="separator" className="mx-3 h-px bg-line-default" />
      <section aria-label="Calendars">
        {groups.map((g, i) => <CalendarGroup key={g.name} {...g} offset={i * 3} />)}
      </section>
    </>
  );
}

"use client";
import { ChevronsUpDown } from "lucide-react";
import { Avatar } from "@/components/ui/display";
import { Icon } from "@/components/ui/icon";
import { Menu } from "@/components/ui/overlays";
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem, useSidebar } from "@/components/ui/sidebar";

/** The signed-in person at the bottom of the sidebar, with an account menu. */
export function NavUser({ user }: { user: { name: string; email: string } }) {
  const { isMobile, state } = useSidebar();
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <Menu
          label={`Account menu for ${user.name}`}
          className="flex w-full"
          placement={!isMobile && state === "collapsed" ? "right-end" : "top-start"}
          items={[
            { label: "Profile", icon: "user" },
            { label: "Billing", icon: "credit-card" },
            { label: "Notifications", icon: "bell" },
            { label: "Sign out", icon: "sign-out", separatorBefore: true },
          ]}
          trigger={({ ref, ...p }) => (
            <SidebarMenuButton ref={ref as React.Ref<HTMLElement>} {...p} size="lg" tooltip={user.name}>
              <Avatar name={user.name} decorative />
              <span className="flex min-w-0 flex-1 flex-col">
                <span className="truncate text-label-medium text-fg-primary">{user.name}</span>
                <span className="truncate text-caption-default">{user.email}</span>
              </span>
              <Icon name={ChevronsUpDown} size={16} />
            </SidebarMenuButton>
          )}
        />
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

"use client";
import type { ReactNode } from "react";
import { Breadcrumbs } from "@/components/ui/nav-extra";
import { SidebarTrigger } from "@/components/ui/sidebar";

/** The bar above the page: sidebar toggle, breadcrumbs and optional actions on the end side. */
export function SiteHeader({ crumbs, actions }: { crumbs: { label: string; href?: string }[]; actions?: ReactNode }) {
  return (
    <header className="sticky top-0 z-[var(--ds-z-sticky)] flex h-14 shrink-0 items-center gap-2 border-b border-line-default bg-surface px-4 md:rounded-t-[inherit]">
      <SidebarTrigger className="-ms-1" />
      <span aria-hidden className="mx-1 h-4 w-px bg-line-default" />
      <Breadcrumbs items={crumbs} />
      {actions && <div className="ms-auto flex items-center gap-2">{actions}</div>}
    </header>
  );
}
